<div class="page-shell dark-section"><header class="page-hero wrap"><span class="eyebrow">Ideas in public</span><h1>Discussions</h1><p>Moderated conversations about the future of Nagpur.</p><a class="pill pill-light" href="<?=url('discussions/create')?>">Start a discussion</a></header><div class="wrap discussion-list"><?php foreach($discussions as $d):?><a class="discussion-row" href="<?=url('discussions/'.$d['slug'])?>"><span class="category"><?=e($d['category'])?></span><div><h3><?=e($d['title'])?></h3><small>Started by <?=e($d['full_name'])?></small></div><span class="replies"><?=e($d['replies'])?> replies</span><span class="arrow">→</span></a><?php endforeach;?><?php if(!$discussions):?><div class="empty-state">No published discussions yet.</div><?php endif;?></div></div>
